N, FAIL = 4, 0.4                       # 상태 1..4, 4 가 끝

def succ(s):                           # (행동, 확률, 보상, 다음 상태) 목록
    out = [('walk', 1.0, -1, s + 1)] if s + 1 <= N else []
    if 2 * s <= N:
        out += [('tram', 1 - FAIL, -2, 2 * s), ('tram', FAIL, -2, s)]
    return out

def value_iteration(gamma=1.0, iters=100):
    V = {s: 0.0 for s in range(1, N + 1)}
    for _ in range(iters):
        Q = {}
        for s in range(1, N):          # 끝 상태 N 은 V=0 고정
            for a, p, r, s2 in succ(s):
                Q[s, a] = Q.get((s, a), 0) + p * (r + gamma * V[s2])
        V = {s: max([q for (t, a), q in Q.items() if t == s], default=0)
             for s in range(1, N + 1)}
    pi = {s: max((a for (t, a) in Q if t == s), key=lambda a: Q[s, a])
          for s in range(1, N)}
    return V, Q, pi

V, Q, pi = value_iteration()
print({k: round(v, 3) for k, v in Q.items()})
print(V, pi)

from collections import defaultdict

counts = defaultdict(lambda: defaultdict(lambda: defaultdict(int)))  # s -> a -> s' -> 횟수
rewards = {}                                                          # (s, a, s') -> 보상

def incorporate(s, a, r, s2):
    rewards[s, a, s2] = r
    counts[s][a][s2] += 1

def successors(s):                      # 횟수를 정규화해 추정 전이확률을 만든다
    out = []
    for a, nxt in counts[s].items():
        total = sum(nxt.values())
        for s2, c in nxt.items():
            out.append((a, round(c / total, 4), rewards[s, a, s2], s2))
    return out

