import random
from collections import defaultdict
N, FAIL = 10, 0.4
def step(s, a): return (-1, s + 1) if a == 'walk' else (-2, s if random.random() < FAIL else 2 * s)
def valid(s): return ['walk', 'tram'] if 2 * s <= N else ['walk']

def explore(episodes, seed):            # 1단계: 무작위 정책으로 돌며 횟수를 센다
    random.seed(seed); cnt = defaultdict(lambda: defaultdict(int)); R = {}
    for _ in range(episodes):
        s = 1
        while s != N:
            a = random.choice(valid(s)); r, s2 = step(s, a)
            cnt[s, a][s2] += 1; R[s, a, s2] = r; s = s2
    return cnt, R

def value_iteration(cnt, R, iters=200):  # 2단계: 추정한 MDP 위에서 가치 반복
    V = defaultdict(float)
    for _ in range(iters):
        Q = {(s, a): sum(c / sum(nx.values()) * (R[s, a, s2] + V[s2]) for s2, c in nx.items())
             for (s, a), nx in cnt.items()}
        for s in range(1, N): V[s] = max(q for (t, a), q in Q.items() if t == s)
    pi = {s: max((a for (t, a) in Q if t == s), key=lambda a: Q[s, a]) for s in range(1, N)}
    return V, pi

for episodes in (3, 10, 200):
    V, pi = value_iteration(*explore(episodes, seed=1))
    trams = [s for s, a in pi.items() if a == 'tram']
    print(episodes, 'V(1)=%.2f' % V[1], 'tram at', trams)

import random
from collections import Counter

def epsilon_greedy(Q, s, actions, eps):
    if random.random() < eps:                 # 확률 ε: 탐험(유효 행동 중 무작위)
        return random.choice(actions)
    return max(actions, key=lambda a: Q.get((s, a), float('-inf')))  # 1-ε: 활용

Q = {(1, 'walk'): -3.0, (1, 'tram'): -4.4}
random.seed(0)
for eps in (0.0, 0.1, 0.4, 1.0):
    c = Counter(epsilon_greedy(Q, 1, ['walk', 'tram'], eps) for _ in range(100000))
    print(eps, {a: round(n / 100000, 3) for a, n in c.items()})

import random
from collections import defaultdict
N, FAIL, EPS = 10, 0.4, 0.4
def step(s, a): return (-1, s + 1) if a == 'walk' else (-2, s if random.random() < FAIL else 2 * s)
def valid(s): return ['walk', 'tram'] if 2 * s <= N else ['walk']

class ModelFreeMC:
    def __init__(self): self.sum, self.cnt, self.rollout = defaultdict(float), defaultdict(int), []
    def Q(self, s, a): return self.sum[s, a] / self.cnt[s, a]
    def get_action(self, s):
        tried = [a for a in valid(s) if self.cnt[s, a] > 0]
        if not tried or random.random() < EPS: return random.choice(valid(s))
        return max(tried, key=lambda a: self.Q(s, a))
    def incorporate_feedback(self, s, a, r, s2, is_end):
        self.rollout.append((s, a, r))
        if not is_end: return                    # 에피소드가 끝나야 효용을 계산할 수 있다
        u = 0.0
        for s_, a_, r_ in reversed(self.rollout):
            u = r_ + 1.0 * u                     # γ = 1
            self.sum[s_, a_] += u; self.cnt[s_, a_] += 1
        self.rollout = []

random.seed(0); agent = ModelFreeMC()
for ep in range(5000):
    s = 1
    while s != N:
        a = agent.get_action(s); r, s2 = step(s, a)
        agent.incorporate_feedback(s, a, r, s2, s2 == N); s = s2
print({(s, a): round(agent.Q(s, a), 2) for (s, a) in sorted(agent.cnt) if s <= 5})

import random
from collections import defaultdict
N, FAIL, EPS, LR = 10, 0.4, 0.4, 0.05
def step(s, a): return (-1, s + 1) if a == 'walk' else (-2, s if random.random() < FAIL else 2 * s)
def valid(s): return ['walk', 'tram'] if 2 * s <= N else ['walk']

def run(off_policy, episodes=20000, seed=1):
    random.seed(seed); Q = defaultdict(float)
    greedy = lambda s: max(valid(s), key=lambda a: Q[s, a])
    act = lambda s: random.choice(valid(s)) if random.random() < EPS else greedy(s)
    for _ in range(episodes):
        s = 1; a = act(s)
        while s != N:
            r, s2 = step(s, a)
            a2 = act(s2) if s2 != N else None           # 실제로 다음에 할 행동(SARSA 의 마지막 A)
            if s2 == N: nxt = 0.0                       # 끝 상태의 가치는 0
            elif off_policy: nxt = Q[s2, greedy(s2)]    # Q-learning: max_a' Q(s', a')
            else: nxt = Q[s2, a2]                       # SARSA: Q(s', a')
            Q[s, a] += LR * (r + nxt - Q[s, a])         # 목표 쪽으로 학습률만큼 당긴다
            s, a = s2, a2
    return Q, {s: greedy(s) for s in range(1, N)}

for name, off in (('SARSA', False), ('Q-learning', True)):
    Q, pi = run(off)
    print(name, 'Q(1,walk)=%.2f Q(5,tram)=%.2f' % (Q[1, 'walk'], Q[5, 'tram']),
          'tram at', [s for s, a in pi.items() if a == 'tram'])

